/**
 * Curated list of common untradeable items that a player may purchase (by incinerating
 * GP, same as any other saving goal) if the item (or one of its variants) is currently
 * sitting in their own real bank. These items have no GE price since they're untradeable,
 * so prices here are flat placeholders meant to be tuned to taste rather than derived
 * from market value.
 * <p>
 * Items are organised into {@link Group}s so that variants of the same reward (charged/
 * uncharged, "(or)" trimmed versions, cosmetic recolours that still confer the item, etc.)
 * all count as satisfying the same purchasable goal. Matching is done by exact
 * {@code ItemComposition} name, so every variant a player might have must be listed
 * explicitly as an alias \u2014 there's no reliable naming pattern to auto-derive them.
 * If you find a variant that isn't recognised, add its exact in-game name to the
 * relevant group's alias list below.
 */
public final class UntradeableCatalog
{
	/** One purchasable goal: a canonical display name/price, plus every exact item name that satisfies it. */
	public static final class Group
	{
		public final String canonicalName;
		public final long price;
		public final List<String> aliases;

		private Group(String canonicalName, long price, String... aliases)
		{
			this.canonicalName = canonicalName;
			this.price = price;
			this.aliases = Arrays.asList(aliases);
		}
	}

	private static final List<Group> GROUPS = new ArrayList<>();
	// Exact item name -> owning group, built once from GROUPS for fast lookup.
	private static final Map<String, Group> ALIAS_INDEX = new HashMap<>();

	private static void group(String canonicalName, long price, String... aliases)
	{
		final Group g = new Group(canonicalName, price, aliases);
		GROUPS.add(g);
		for (String alias : aliases)
		{
			ALIAS_INDEX.put(alias, g);
		}
	}

