			"Void ranger helm", "Void ranger helm (or)", "Void ranger helm (l)", "Void ranger helm (l)(or)");
		group("Void melee helm", 500_000L,
			"Void melee helm", "Void melee helm (or)", "Void melee helm (l)", "Void melee helm (l)(or)");
		group("Elite void top", 500_000L,
			"Elite void top", "Elite void top (or)", "Elite void top (l)", "Elite void top (l)(or)");
		group("Elite void robe", 500_000L,
			"Elite void robe", "Elite void robe (or)", "Elite void robe (l)", "Elite void robe (l)(or)");
		group("Fighter torso", 500_000L,
			"Fighter torso", "Fighter torso (or)", "Fighter torso (l)", "Fighter torso (l)(or)");
	}

	private UntradeableCatalog()
	{
	}

	/** Returns the group for the given exact item name (any alias), or null if not catalogued. */
	private static Group resolve(String exactName)
	{
		return exactName == null ? null : ALIAS_INDEX.get(exactName);
	}

	/** Returns true if the given exact item name is buyable via this catalog (any alias). */
	public static boolean isCatalogItem(String exactName)
	{
		return resolve(exactName) != null;
	}

	/**
	 * Returns the canonical (goal/display) name for the given exact item name, or the
	 * name unchanged if it isn't part of any group.
	 */
	public static String getCanonicalName(String exactName)
	{
		final Group g = resolve(exactName);
		return g != null ? g.canonicalName : exactName;
	}

	/** Returns the GP price for the given canonical or exact item name, or 0 if not in the catalog. */
	public static long getPrice(String canonicalOrExactName)
	{
		final Group g = resolve(canonicalOrExactName);
		return g != null ? g.price : 0L;
	}

	/** Returns an unmodifiable view of all groups. */
	public static List<Group> allGroups()
	{
		return java.util.Collections.unmodifiableList(GROUPS);
	}
}

