	private JPanel buildGoalSection()
	{
		final JPanel sec = section("Saving For");
		final Upgrade goal = mgr.getSelectedGoal();
		final String untradeableGoal = mgr.getSelectedUntradeableGoal();
		if (goal == null && untradeableGoal == null)
		{
			sec.add(dim("No goal selected. Choose one below."));
			return sec;
		}

		final String displayName = goal != null ? goal.getDisplayName() : untradeableGoal;
		final long progress = goal != null ? mgr.getProgress(goal) : mgr.getUntradeableProgress(untradeableGoal);
		final long cost = goal != null ? mgr.getCurrentCost(goal) : mgr.getUntradeablePrice(untradeableGoal);

		final JLabel name = new JLabel(displayName);
		name.setForeground(GOAL_BLUE);
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		sec.add(name);
		sec.add(Box.createVerticalStrut(2));

		final int pct = (int) Math.min(100, (progress * 100L) / Math.max(1L, cost));

		final JLabel detail = new JLabel(formatGp(progress) + " / " + formatGp(cost));
		detail.setForeground(Color.LIGHT_GRAY);
		detail.setAlignmentX(Component.LEFT_ALIGNMENT);
		sec.add(detail);
		sec.add(Box.createVerticalStrut(4));

		final JProgressBar bar = new JProgressBar(0, 100);
		bar.setValue(pct);
		bar.setStringPainted(true);
		bar.setString(pct + "%");
		bar.setFont(FontManager.getRunescapeSmallFont());
		bar.setForeground(GOAL_BLUE);
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setBorderPainted(false);
		bar.setAlignmentX(Component.LEFT_ALIGNMENT);
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 14));
		sec.add(bar);
		sec.add(Box.createVerticalStrut(4));

		final JButton clearBtn = new JButton("Clear goal");
		clearBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
		clearBtn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		clearBtn.addActionListener(e -> {
			if (goal != null)
			{
				mgr.selectGoal(null);
			}
			else
			{
				mgr.selectUntradeableGoal(null);
			}
		});
		sec.add(clearBtn);

		sec.add(Box.createVerticalStrut(2));
		final JLabel hint = new JLabel(
			"<html><body style='width:150px'>"
				+ "Open a bank and drag coins onto the Bank Incinerator to make progress."
				+ "</body></html>");
		hint.setForeground(Color.GRAY);
		hint.setAlignmentX(Component.LEFT_ALIGNMENT);
		sec.add(hint);

		return sec;
	}

